def icon_svg(body):
 return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none" stroke="#63391b" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"><defs><linearGradient id="paper" x2=".3" y2="1"><stop stop-color="#fff3ce"/><stop offset="1" stop-color="#e9bd75"/></linearGradient><linearGradient id="bronze" x2=".25" y2="1"><stop stop-color="#ffe7a0"/><stop offset=".45" stop-color="#bd8535"/><stop offset="1" stop-color="#785022"/></linearGradient><linearGradient id="copper" x2=".3" y2="1"><stop stop-color="#f4c27e"/><stop offset=".45" stop-color="#ce7545"/><stop offset="1" stop-color="#813b27"/></linearGradient><linearGradient id="gold" x2=".3" y2="1"><stop stop-color="#fff1b7"/><stop offset=".5" stop-color="#edba4c"/><stop offset="1" stop-color="#c18229"/></linearGradient></defs>{body}</svg>'''
for name,body in icons.items():(p/f'{name}.svg').write_text(icon_svg(body))
